package io.github.rebrowser.bridge;
import static org.junit.Assert.*;
import io.github.rebrowser.bootstrap.*;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.Test;
public class DocumentRouteTest {
 static final String R="r_00000000000000000000000000000000",S="b_00000000000000000000000000000000";
 static class F {
  final AtomicReference<ComponentGate.SourceView> source=new AtomicReference<>(ComponentGate.SourceView.acceptedNative(new Object(),new byte[16]));final ComponentGate gate=ComponentGate.forNativeSource(ProcessRole.MAIN,source::get);final ComponentGate.DataEpochPin pin=gate.captureDataEpoch(gate.requireBusiness());final Object port=new Object();boolean nativeCurrent=true;
  final DocumentLease lease=new DocumentLease(port,pin,"ctx_synthetic","ses_synthetic",()->{if(!nativeCurrent)throw new SecurityException();});
  BridgeMessages.Message hello(){return BridgeMessages.parse("{\"protocol\":\"rebrowser.connector/1\",\"kind\":\"HELLO\",\"connectorVersion\":\"1.0.0\",\"documentInstanceHint\":\"untrusted\"}");}
  void ready(){lease.spendHello(port,hello());BridgeMessages.nativeReady(lease.nativeBinding(),MusicConnector.ACTION);lease.readyPostReturned(port);}
  String frame(String kind,String fields){String ready=BridgeMessages.nativeReady(lease.nativeBinding(),MusicConnector.ACTION);String prefix=ready.substring(0,ready.indexOf(",\"limits\""));return prefix.replace("\"kind\":\"READY\"","\"kind\":\""+kind+"\"")+","+fields+"}";}
  DocumentLease.Received receive(String kind,String fields){return lease.receive(port,BridgeMessages.parse(frame(kind,fields)));}
  DocumentLease.Received result(String payload){return receive("RESULT","\"requestId\":\""+R+"\",\"outcome\":\"observed\",\"evidenceKind\":\"page-observation\",\"result\":"+payload);}
 }
 @Test public void nativeHelloAndReadyReturnNeededBeforeAnyPositiveEnvelope(){F f=new F();assertThrows(SecurityException.class,()->f.receive("ACCEPTED","\"requestId\":\""+R+"\""));assertThrows(SecurityException.class,()->f.lease.spendHello(f.port,f.hello()));F early=new F();early.lease.spendHello(early.port,early.hello());assertThrows(SecurityException.class,()->early.receive("ACCEPTED","\"requestId\":\""+R+"\""));assertThrows(SecurityException.class,()->early.lease.readyPostReturned(early.port));F valid=new F();valid.ready();assertEquals(BridgeMessages.Kind.ACCEPTED,valid.receive("ACCEPTED","\"requestId\":\""+R+"\"").message().kind());}
 @Test public void unknownVersionSpendsHelloAndCannotRetry(){F f=new F();BridgeMessages.Message bad=BridgeMessages.parse("{\"protocol\":\"rebrowser.connector/1\",\"kind\":\"HELLO\",\"connectorVersion\":\"wrong\",\"documentInstanceHint\":\"x\"}");assertThrows(SecurityException.class,()->f.lease.spendHello(f.port,bad));assertEquals(DocumentLease.State.RETIRED,f.lease.state());assertThrows(SecurityException.class,()->f.lease.spendHello(f.port,f.hello()));}
 @Test public void exactPortCannotBeReplacedByMatchingHint(){F f=new F();f.ready();assertThrows(SecurityException.class,()->f.lease.receive(new Object(),BridgeMessages.parse(f.frame("ACCEPTED","\"requestId\":\""+R+"\""))));}
 @Test public void bindingTokensRotateEvenOnSameNativeEpochAndMetadata(){F a=new F(),b=new F();a.ready();b.ready();assertNotEquals(a.lease.nativeBinding().documentLeaseHex(),b.lease.nativeBinding().documentLeaseHex());assertThrows(SecurityException.class,()->b.lease.receive(b.port,BridgeMessages.parse(a.frame("ACCEPTED","\"requestId\":\""+R+"\""))));}
 @Test public void wrongEpochAndSessionGenerationCannotPass(){F f=new F();f.ready();String original=f.frame("ACCEPTED","\"requestId\":\""+R+"\"");assertThrows(SecurityException.class,()->f.lease.receive(f.port,BridgeMessages.parse(original.replace("\"sessionGeneration\":0","\"sessionGeneration\":1"))));assertThrows(SecurityException.class,()->f.lease.receive(f.port,BridgeMessages.parse(original.replace("00000000000000000000000000000000","11111111111111111111111111111111"))));}
 @Test public void pageCannotSendReadyCommandCreditOrCancelToNative(){for(String kind:new String[]{"READY","COMMAND","STREAM_CREDIT","CANCEL"}){F f=new F();f.ready();BridgeMessages.Message message;if(kind.equals("READY"))message=BridgeMessages.parse(BridgeMessages.nativeReady(f.lease.nativeBinding(),MusicConnector.ACTION));else if(kind.equals("COMMAND"))message=BridgeMessages.parse(BridgeMessages.nativeObserve(f.lease.nativeBinding(),R,MusicConnector.ACTION));else if(kind.equals("STREAM_CREDIT"))message=BridgeMessages.parse(BridgeMessages.nativeCredit(f.lease.nativeBinding(),S,0,1,1));else message=BridgeMessages.parse(f.frame(kind,"\"requestId\":\""+R+"\""));assertThrows(SecurityException.class,()->f.lease.receive(f.port,message));}}
 @Test public void eventContiguityAndDuplicatesNeverBecomeAcknowledgements(){F f=new F();f.ready();String fields="\"eventSequence\":0,\"eventType\":\"x\",\"resourceRef\":\"x\",\"payload\":{}";f.receive("EVENT",fields);assertThrows(SecurityException.class,()->f.receive("EVENT",fields));assertThrows(SecurityException.class,()->f.receive("EVENT",fields.replace(":0,",":2,")));}
 @Test public void receivedCapsuleRevokedAfterSourceOrNativeNavigationFence(){F f=new F();f.ready();DocumentLease.Received received=f.receive("ACCEPTED","\"requestId\":\""+R+"\"");f.nativeCurrent=false;assertThrows(SecurityException.class,received::message);F g=new F();g.ready();DocumentLease.Received old=g.receive("ACCEPTED","\"requestId\":\""+R+"\"");g.source.set(ComponentGate.SourceView.acceptedNative(new Object(),new byte[16]));assertThrows(SecurityException.class,old::message);}
 @Test public void privateLeaseAndReceivedHaveNoPublicIssuingConstructor(){assertEquals(0,DocumentLease.class.getConstructors().length);assertEquals(0,DocumentLease.Received.class.getConstructors().length);F f=new F();f.ready();f.lease.retire();assertThrows(SecurityException.class,()->f.lease.readyPostReturned(f.port));}
 @Test public void ingressByteAndObjectCreditOutlivesBorrowedMethodReturn(){BridgeBudget.Ingress i=new BridgeBudget.Ingress();BridgeBudget.Envelope[] e=new BridgeBudget.Envelope[8];for(int n=0;n<8;n++)e[n]=i.retain("x");assertEquals(8,i.objects());assertThrows(BridgeBudget.Rejected.class,()->i.retain("y"));e[0].borrowed();assertEquals(8,i.objects());e[0].close();e[0].close();assertEquals(7,i.objects());for(int n=1;n<8;n++)e[n].close();assertEquals(0,i.objects());}
 @Test public void ingressCountsUtf8AndNeverRepairsSurrogates(){BridgeBudget.Ingress i=new BridgeBudget.Ingress();assertThrows(IllegalArgumentException.class,()->i.retain("\ud800"));assertThrows(BridgeBudget.Rejected.class,()->i.retain(new String(new char[32769]).replace('\0','书')));assertEquals(0,i.objects());}
 @Test public void sourceLockedLeaseCanRetireButCannotPublish(){F f=new F();f.ready();f.source.set(ComponentGate.SourceView.untrusted(ComponentGate.SourceState.LOCKED));f.lease.retire();assertEquals(DocumentLease.State.RETIRED,f.lease.state());assertThrows(SecurityException.class,()->f.lease.nativeBinding());}
}
